INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Bilan digital de fin d''année : la checklist TPE en 20 points', 'bilan-digital-fin-annee', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Stratégie digitale', 'Une heure en décembre pour vérifier votre site, votre fiche Google, vos réseaux, vos contacts et vos accès. Vingt points à cocher, et trois priorités pour l''année.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Une fois par an, prenez une heure pour vérifier votre site, votre fiche Google, vos réseaux sociaux, vos contacts clients et vos accès.</li> <li>La plupart des points se corrigent en quelques minutes : des horaires à jour, un lien cassé, un ancien salarié qui a encore accès à la page Facebook.</li> <li>Notez ce qui reste à faire et choisissez trois priorités pour l''année qui vient, pas vingt.</li> </ul> </div> <p>Décembre arrive, l''activité ralentit un peu ou s''emballe avant les fêtes. C''est le bon moment pour regarder votre présence en ligne avec les yeux d''un client : est-ce qu''il trouve vos horaires de fin d''année ? Est-ce que le formulaire du site fonctionne encore ? Est-ce que la dernière publication date de juillet ?</p> <p>Voici la checklist en 20 points, rangée en cinq familles. Cochez au fur et à mesure, et gardez la liste pour l''an prochain.</p> <h2>Votre site internet</h2> <ul class="checklist"> <li><strong>Le site s''ouvre bien sur téléphone</strong>, rapidement, sans texte coupé ni bouton trop petit.</li> <li><strong>Le formulaire de contact arrive</strong> : envoyez-vous une demande test et vérifiez qu''elle arrive dans la bonne boîte, et pas dans les indésirables.</li> <li><strong>Les prix, services et photos sont à jour</strong>, et les offres terminées ont disparu.</li> <li><strong>Le nom de domaine est à votre nom</strong> et se renouvelle automatiquement. Notre article sur le <a href="/blog/nom-de-domaine-entreprise">nom de domaine</a> explique comment le vérifier.</li> <li><strong>Les mentions légales et la politique de confidentialité</strong> sont présentes et correspondent à ce que fait le site (formulaire, cookies, statistiques).</li> </ul> <h2>Votre fiche Google</h2> <ul class="checklist"> <li><strong>Les horaires exceptionnels des fêtes</strong> sont renseignés : Noël, jour de l''An, fermeture annuelle. Google permet de les ajouter à l''avance.</li> <li><strong>L''adresse, le téléphone et la catégorie</strong> sont exacts.</li> <li><strong>Les photos datent de moins d''un an</strong> et montrent votre vraie vitrine, vos réalisations, votre équipe.</li> <li><strong>Chaque avis a une réponse</strong>, y compris les mauvais. Voir notre guide sur les <a href="/blog/avis-google-entreprise">avis Google</a>.</li> </ul> <h2>Vos réseaux sociaux</h2> <ul class="checklist"> <li><strong>Les informations de la page</strong> (horaires, téléphone, lien vers le site) sont les mêmes que sur Google.</li> <li><strong>La dernière publication a moins d''un mois.</strong> Si vous manquez d''idées, piochez dans nos <a href="/blog/idees-publications-reseaux-sociaux">30 idées de publications</a>.</li> <li><strong>Les messages privés n''attendent pas de réponse</strong> depuis des semaines.</li> <li><strong>Vous avez au moins deux administrateurs de confiance</strong>, avec la double authentification activée.</li> </ul> <h2>Vos contacts clients</h2> <ul class="checklist"> <li><strong>Vos contacts sont rassemblés à un seul endroit</strong> (tableur, logiciel de gestion), et pas dispersés entre le téléphone, les e-mails et les carnets.</li> <li><strong>Les devis sans réponse ont été relancés.</strong> Notre article sur les <a href="/blog/relances-automatiques-devis-factures">relances automatiques</a> montre comment ne plus en oublier.</li> <li><strong>Les personnes inscrites à votre newsletter</strong> ont donné leur accord, et chaque envoi permet de se désinscrire.</li> </ul> <h2>Vos accès et votre sécurité</h2> <ul class="checklist"> <li><strong>Les anciens salariés et prestataires n''ont plus d''accès</strong> : site, messagerie, réseaux sociaux, fiche Google.</li> <li><strong>Les mots de passe importants sont uniques</strong> et rangés dans un gestionnaire de mots de passe.</li> <li><strong>Une sauvegarde récente existe</strong> pour le site, les fichiers clients et la comptabilité, et vous savez la restaurer.</li> <li><strong>Vous savez où sont vos accès</strong> : qui gère l''hébergement, le nom de domaine, la messagerie, et comment le joindre.</li> </ul> <h2>Après la checklist : trois priorités, pas vingt</h2> <p>Vous aurez sans doute coché la majorité des points. Pour les autres, ne cherchez pas à tout régler en janvier. Classez-les :</p> <table class="table-article"> <thead><tr><th>Type de point</th><th>Exemples</th><th>Quand le traiter</th></tr></thead> <tbody> <tr><td>Urgent et rapide</td><td>Horaires des fêtes, formulaire en panne, ancien salarié encore administrateur</td><td>Cette semaine</td></tr> <tr><td>Important</td><td>Photos à refaire, avis sans réponse, sauvegarde absente</td><td>Au premier trimestre</td></tr> <tr><td>Projet</td><td>Refonte du site, prise de rendez-vous en ligne, newsletter</td><td>À budgéter pour l''année</td></tr> </tbody> </table> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un institut de beauté à Saint-Leu</p> <p>La gérante fait la checklist un dimanche de décembre. Elle découvre que le formulaire de son site envoyait les demandes vers l''adresse d''une ancienne employée, et que sa fiche Google affichait des horaires d''avant les travaux. Elle corrige les deux en une demi-heure, ajoute les horaires du 24 et du 31 décembre, et garde deux projets pour l''année : des photos professionnelles et la réservation en ligne.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Le diagnostic gratuit reprend ces points avec vous : ce qui marche, ce qui bloque, et par quoi commencer. Si un chantier ressort, nous vous donnons le prix de la grille avant de démarrer, par exemple 390 € pour optimiser votre fiche Google et vos avis.</p> <p><a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a> · <a href="/tarifs" class="encadre-lien">Voir les tarifs</a></p> </div> <h2>Questions fréquentes</h2> <h3>Combien de temps prend ce bilan ?</h3> <p>Comptez une heure si vous avez vos accès sous la main. Le plus long est souvent de retrouver qui gère quoi : le noter une fois vous fera gagner du temps l''année suivante.</p> <h3>Comment indiquer les horaires de fin d''année sur Google ?</h3> <p>Dans votre fiche d''établissement, ajoutez des horaires exceptionnels pour chaque jour concerné (jour férié, fermeture, horaires réduits). Vos horaires habituels restent en place et reprennent ensuite automatiquement.</p> <h3>Faut-il refaire ce bilan chaque année ?</h3> <p>Oui, au minimum. Les horaires, les équipes et les offres changent, et les accès oubliés s''accumulent. Certains points, comme les avis et les messages, gagnent à être vérifiés chaque semaine.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://support.google.com/business/answer/6303076?hl=fr" target="_blank" rel="noopener">Google : définir des horaires exceptionnels</a>.</li> <li><a href="https://www.cnil.fr/fr/passer-laction/rgpd-les-premieres-etapes" target="_blank" rel="noopener">CNIL : RGPD, les premières étapes</a>.</li> <li><a href="https://www.cybermalveillance.gouv.fr/tous-nos-contenus/bonnes-pratiques/10-mesures-essentielles-assurer-securite-numerique" target="_blank" rel="noopener">Cybermalveillance.gouv.fr : les 10 mesures essentielles pour votre cybersécurité</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Bilan digital de fin d''année : checklist TPE en 20 points', 'Site, fiche Google, réseaux sociaux, contacts clients, accès : la checklist en 20 points pour faire le bilan digital de votre TPE en une heure.', 'bilan digital, checklist digitale TPE, audit présence en ligne, fiche Google horaires fêtes, Réunion', '/assets/images/blog/bilan-digital-fin-annee.webp', '/assets/images/blog/bilan-digital-fin-annee.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('SEO, CTR, CRM : 15 mots du digital expliqués simplement', 'lexique-marketing-digital', (SELECT id FROM service_categories WHERE slug = 'seo'), 'Stratégie digitale', 'Votre prestataire parle une autre langue ? Le petit lexique pour comprendre vos devis, poser les bonnes questions et ne plus signer à l''aveugle.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>SEO, CTR, CRM, landing page… le jargon du digital cache souvent des idées simples. Les comprendre vous aide à poser les bonnes questions avant de signer.</li> <li>Trois familles reviennent sans cesse : être trouvé (SEO, SEA), convaincre (taux de conversion, appel à l''action) et suivre ses clients (CRM, KPI).</li> <li>Un bon prestataire doit pouvoir vous expliquer chaque terme de son devis en une phrase. S''il n''y arrive pas, demandez-lui de le faire.</li> </ul> </div> <p>Le devis indique « optimisation SEO on-page », « suivi des KPI » et « intégration CRM ». Vous hochez la tête pendant le rendez-vous, puis vous signez sans être sûr de savoir ce que vous achetez. C''est fréquent, et c''est dommage : ces mots désignent presque toujours des choses très concrètes.</p> <p>Voici 15 termes qui reviennent dans les devis et les rapports, expliqués simplement. Pour le vocabulaire de l''intelligence artificielle, voir notre <a href="/blog/lexique-ia-tpe">lexique de l''IA</a>.</p> <h2>Être trouvé</h2> <h3>SEO (référencement naturel)</h3> <p>L''ensemble du travail qui aide votre site à sortir dans les résultats gratuits de Google : contenu utile, pages bien construites, site rapide, liens d''autres sites. Les résultats prennent des semaines ou des mois, mais ne s''arrêtent pas quand vous cessez de payer.</p> <h3>SEA (référencement payant)</h3> <p>Les annonces que vous payez pour apparaître en haut de Google, en général au clic. L''effet est immédiat, et s''arrête dès que le budget s''arrête. SEO et SEA se complètent.</p> <h3>Mot-clé (ou requête)</h3> <p>Ce que votre client tape dans Google : « plombier Saint-Pierre », « gâteau d''anniversaire Saint-Denis ». Un bon site parle avec les mots de ses clients, pas avec ceux du métier.</p> <h3>Référencement local</h3> <p>La partie du SEO qui vous fait apparaître sur Google Maps et dans les résultats « près de moi ». Elle repose surtout sur votre fiche Google et vos avis. Voir notre guide de la <a href="/blog/fiche-google-reunion">fiche Google</a>.</p> <h3>Backlink (lien entrant)</h3> <p>Un lien vers votre site posté sur un autre site : annuaire professionnel, partenaire, article de presse. Pour Google, c''est un signe de confiance, à condition que le site qui vous cite soit sérieux et proche de votre activité.</p> <h2>Convaincre</h2> <h3>Landing page (page d''atterrissage)</h3> <p>Une page unique, construite autour d''une seule action : demander un devis, réserver, s''inscrire. Souvent utilisée comme destination d''une publicité. Voir notre article sur la <a href="/blog/landing-page-definition">landing page</a>.</p> <h3>Appel à l''action (CTA)</h3> <p>Le bouton ou la phrase qui dit au visiteur quoi faire : « Demander mon devis », « Appeler », « Réserver ». CTA vient de l''anglais <em>call to action</em>. Un seul appel clair vaut mieux que cinq boutons différents.</p> <h3>Taux de conversion</h3> <p>La part des visiteurs qui font l''action attendue. Si 200 personnes visitent votre page et que 4 demandent un devis, le taux de conversion est de 2 %. C''est souvent plus utile à suivre que le nombre de visiteurs.</p> <h3>Responsive</h3> <p>Un site qui s''adapte à la taille de l''écran : ordinateur, tablette, téléphone. Aujourd''hui, c''est un minimum : une grande partie des visiteurs arrivent depuis un mobile.</p> <h2>Mesurer</h2> <h3>Impressions</h3> <p>Le nombre de fois où votre annonce, votre publication ou votre page est apparue à l''écran. Une impression n''est pas une lecture : la personne a pu faire défiler sans regarder.</p> <h3>CTR (taux de clic)</h3> <p>La part des impressions qui donnent un clic. 1 000 impressions et 30 clics font un CTR de 3 %. Un CTR faible sur Google signale souvent un titre ou une description peu engageants.</p> <h3>Taux de rebond</h3> <p>La part des visiteurs qui repartent sans aller plus loin. Un taux élevé n''est pas toujours grave (le client a peut-être trouvé votre téléphone et appelé), mais sur une page de vente, c''est un signal à regarder.</p> <h3>KPI (indicateur clé)</h3> <p>Le chiffre qui dit si une action marche : demandes de devis par mois, réservations, appels depuis la fiche Google. Choisissez-en deux ou trois, liés à votre chiffre d''affaires, plutôt que vingt.</p> <h2>Suivre ses clients</h2> <h3>CRM (gestion de la relation client)</h3> <p>Le logiciel, ou le tableur bien tenu, où vous rangez vos contacts, vos devis, vos échanges et vos relances. CRM vient de l''anglais <em>customer relationship management</em>. Il évite de perdre un prospect parce qu''il était noté sur un post-it.</p> <h3>Lead (prospect)</h3> <p>Une personne qui a montré un intérêt : formulaire rempli, message envoyé, appel. Un lead n''est pas encore un client ; tout l''enjeu est de lui répondre vite et de le relancer.</p> <table class="table-article"> <thead><tr><th>Sur votre devis</th><th>La question à poser</th></tr></thead> <tbody> <tr><td>« Optimisation SEO »</td><td>Quelles pages, quels mots-clés, et comment je verrai le résultat ?</td></tr> <tr><td>« Suivi des KPI »</td><td>Quels indicateurs, à quelle fréquence, et sous quelle forme ?</td></tr> <tr><td>« Intégration CRM »</td><td>Quel outil, qui y aura accès, et mes données restent-elles à moi ?</td></tr> <tr><td>« Campagne SEA »</td><td>Quel budget publicitaire, en plus des honoraires, et pour quel objectif ?</td></tr> </tbody> </table> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un gérant de salle de sport à Saint-Paul</p> <p>Il reçoit deux devis pour « le référencement ». L''un promet « la première page Google » sans détail ; l''autre liste les pages à retravailler, les cinq requêtes visées et un rapport mensuel avec les clics et les demandes d''essai. Avec ce lexique en tête, il pose les mêmes questions aux deux prestataires et choisit celui qui sait y répondre.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Nos devis reprennent les lignes de la grille tarifaire, expliquées en français courant. Par exemple : SEO local (fiche Google et avis) à 390 €, audit technique et optimisation des pages à 590 €, site vitrine à partir de 990 €.</p> <p><a href="/services#seo" class="encadre-lien">Voir l''offre SEO</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Quelle est la différence entre SEO et SEA ?</h3> <p>Le SEO vise les résultats gratuits de Google et demande du temps. Le SEA, ce sont les annonces payantes, visibles tout de suite mais seulement tant que vous payez. Une petite entreprise commence souvent par le SEO local et ajoute de la publicité pour une offre précise.</p> <h3>Qu''est-ce qu''un bon taux de conversion ?</h3> <p>Il n''y a pas de chiffre universel : il dépend du secteur, du prix et de l''action demandée. Le plus utile est de comparer votre propre taux d''un mois à l''autre, et après chaque changement de page.</p> <h3>Une TPE a-t-elle besoin d''un CRM ?</h3> <p>Elle a besoin d''un endroit unique pour suivre ses contacts et ses devis. Un tableur bien tenu suffit au début ; un logiciel devient utile quand les relances se multiplient ou que plusieurs personnes suivent les clients.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr" target="_blank" rel="noopener">Google : guide de démarrage en référencement (SEO)</a>.</li> <li><a href="https://support.google.com/google-ads/answer/2615875?hl=fr" target="_blank" rel="noopener">Google Ads : taux de clic (CTR)</a>.</li> <li><a href="https://www.cnil.fr/fr/la-prospection-commerciale-par-courrier-electronique" target="_blank" rel="noopener">CNIL : la prospection commerciale par courrier électronique</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'SEO, CTR, CRM : 15 mots du digital expliqués simplement', 'SEO, SEA, CTR, taux de conversion, CRM, landing page : le lexique du marketing digital pour comprendre vos devis et vos rapports, sans jargon.', 'lexique marketing digital, définition SEO, CTR définition, CRM définition, taux de conversion', '/assets/images/blog/lexique-marketing-digital.webp', '/assets/images/blog/lexique-marketing-digital.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Audit SEO gratuit : lire son rapport pas à pas', 'audit-seo-lire-rapport', (SELECT id FROM service_categories WHERE slug = 'seo'), 'SEO', 'Vous avez lancé l''audit et obtenu une note. Que veut dire chaque ligne, et par quoi commencer pour gagner des places sur Google ?', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>L''audit SEO gratuit de DIGITA vérifie 10 points techniques de la page que vous testez et donne une note sur 100.</li> <li>Chaque ligne est verte (bon), orange (à améliorer) ou rouge (à corriger). Commencez par les rouges, et en particulier par le titre, le HTTPS et l''affichage mobile.</li> <li>La note mesure la base technique d''une page, pas votre position sur Google : un contenu utile et une fiche Google soignée comptent au moins autant.</li> </ul> </div> <p>Vous avez saisi l''adresse de votre site dans l''<a href="/outils/audit-seo">audit SEO gratuit</a>, et vous obtenez 65 sur 100. Bonne ou mauvaise nouvelle ? Et surtout, par quoi commencer ? Ce guide reprend le rapport ligne par ligne, avec ce que chaque point vérifie et comment le corriger.</p> <h2>Comment la note est calculée</h2> <p>L''outil ouvre la page que vous indiquez, comme le ferait un navigateur, et vérifie 10 points. Chacun vaut 10 points : la note totale est donc le pourcentage de points obtenus. Un point orange en rapporte la moitié, un point rouge aucun.</p> <p>Deux limites à garder en tête : l''outil ne regarde que la page testée (pas tout le site), et il ne mesure ni la qualité du texte ni votre popularité. Testez donc aussi vos pages importantes, pas seulement l''accueil.</p> <h2>Les 10 lignes du rapport</h2> <table class="table-article"> <thead><tr><th>Ligne</th><th>Ce qui est vérifié</th><th>Vert si…</th></tr></thead> <tbody> <tr><td>Balise Title</td><td>Le titre de la page affiché dans Google et dans l''onglet</td><td>Il fait entre 30 et 60 caractères</td></tr> <tr><td>Meta Description</td><td>Le résumé qui peut s''afficher sous le titre dans Google</td><td>Il fait entre 120 et 160 caractères</td></tr> <tr><td>Balise H1</td><td>Le titre principal visible sur la page</td><td>Il y en a exactement un</td></tr> <tr><td>Images Alt</td><td>Le texte alternatif des images</td><td>Toutes les images ont un attribut alt</td></tr> <tr><td>HTTPS</td><td>La connexion sécurisée (le cadenas)</td><td>L''adresse commence par https</td></tr> <tr><td>Temps de chargement</td><td>Le temps de réponse de la page lors du test</td><td>Moins de 2 secondes (orange jusqu''à 4)</td></tr> <tr><td>Mobile (viewport)</td><td>La balise qui adapte la page aux téléphones</td><td>Elle est présente</td></tr> <tr><td>Open Graph</td><td>Les informations utilisées quand la page est partagée sur les réseaux</td><td>Les balises sont présentes</td></tr> <tr><td>Liens internes</td><td>Les liens vers vos autres pages</td><td>Au moins 3 liens internes</td></tr> <tr><td>Schema.org</td><td>Les données structurées qui décrivent l''entreprise ou la page à Google</td><td>Elles sont détectées</td></tr> </tbody> </table> <h2>Par quoi commencer</h2> <ol class="etapes"> <li><strong>Le HTTPS.</strong> Un site sans cadenas affiche « Non sécurisé » dans le navigateur, ce qui fait fuir les visiteurs. La plupart des hébergeurs proposent un certificat gratuit : c''est souvent un réglage à activer.</li> <li><strong>Le mobile.</strong> Si la balise viewport manque, la page s''affiche en tout petit sur téléphone. C''est en général le signe d''un site ancien, à faire vérifier.</li> <li><strong>Le titre et la description.</strong> Ils forment votre « annonce » gratuite dans Google. Mettez-y votre métier et votre zone : « Plombier à Saint-Pierre, dépannage 7 j/7 | Hoarau Plomberie » plutôt que « Accueil ».</li> <li><strong>Le H1.</strong> Un seul titre principal, qui dit clairement ce que vous faites et où.</li> <li><strong>La vitesse.</strong> Le plus souvent, ce sont les photos trop lourdes. Compressez-les avant de les mettre en ligne.</li> <li><strong>Le reste</strong> (textes alternatifs, Open Graph, liens internes, données structurées) : des améliorations utiles, souvent rapides pour votre prestataire.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : une boulangerie à Saint-André, note de 55 sur 100</p> <p>Le rapport montre le titre « Accueil » (orange, trop court), aucune meta description (rouge), deux H1 (orange), un chargement de 5 secondes (rouge) à cause de photos de 4 Mo, et pas de données structurées (orange). En une après-midi, son prestataire réécrit le titre et la description, garde un seul H1 et compresse les photos. Au nouveau test, la note dépasse 80, et la page s''ouvre beaucoup plus vite sur téléphone.</p> </div> <h2>Ce que l''audit ne mesure pas</h2> <ul> <li><strong>Le contenu</strong> : une page qui répond vraiment aux questions de vos clients, avec vos prix, votre zone et vos réalisations.</li> <li><strong>Votre fiche Google et vos avis</strong>, qui pèsent lourd pour les recherches locales. Voir notre guide de la <a href="/blog/fiche-google-reunion">fiche Google</a>.</li> <li><strong>Les liens d''autres sites</strong> vers le vôtre, et votre notoriété.</li> <li><strong>Votre position réelle</strong> sur une requête : pour la suivre, utilisez Google Search Console, gratuit.</li> </ul> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>L''audit en ligne est gratuit et sans inscription. Pour aller plus loin : SEO local (fiche Google et avis) à 390 €, audit technique et optimisation des pages à 590 €, ou audit complet avec plan de contenus sur 3 mois à 1 200 €.</p> <p><a href="/outils/audit-seo" class="encadre-lien">Lancer l''audit gratuit</a> · <a href="/services#seo" class="encadre-lien">Voir l''offre SEO</a></p> </div> <h2>Questions fréquentes</h2> <h3>Quelle note viser à l''audit SEO ?</h3> <p>Visez au moins 80 sur 100 sur vos pages principales, avec aucune ligne rouge. Au-delà, chaque point gagné compte moins que la qualité de vos contenus et de votre fiche Google.</p> <h3>Pourquoi ma note change-t-elle d''un test à l''autre ?</h3> <p>Le temps de chargement est mesuré au moment du test : il varie selon la charge du serveur et du réseau. Les autres lignes ne bougent que si la page a été modifiée.</p> <h3>Une bonne note garantit-elle la première page de Google ?</h3> <p>Non. Elle montre que la base technique de la page est saine. Le classement dépend aussi du contenu, de la concurrence sur la requête, de votre fiche Google et des liens vers votre site.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://developers.google.com/search/docs/fundamentals/seo-starter-guide?hl=fr" target="_blank" rel="noopener">Google : guide de démarrage en référencement (SEO)</a>.</li> <li><a href="https://developers.google.com/search/docs/appearance/title-link?hl=fr" target="_blank" rel="noopener">Google : influencer les liens de titre dans les résultats de recherche</a>.</li> <li><a href="https://developers.google.com/search/docs/appearance/structured-data/intro-structured-data?hl=fr" target="_blank" rel="noopener">Google : présentation des données structurées</a>.</li> <li><a href="https://search.google.com/search-console/about?hl=fr" target="_blank" rel="noopener">Google Search Console</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Audit SEO gratuit : lire son rapport pas à pas', 'Title, meta description, H1, HTTPS, vitesse, mobile : les 10 lignes de l''audit SEO gratuit de DIGITA expliquées, et par quoi commencer pour progresser.', 'audit SEO gratuit, rapport SEO, balise title, meta description, référencement site Réunion', '/assets/images/blog/audit-seo-lire-rapport.webp', '/assets/images/blog/audit-seo-lire-rapport.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Créer un logo professionnel : la méthode en 5 étapes', 'creer-logo-entreprise', (SELECT id FROM service_categories WHERE slug = 'creation-web'), 'Identité visuelle', 'Un logo ne se choisit pas sur un coup de cœur. Brief, pistes, tests en petit format, fichiers à récupérer et dépôt à l''INPI : la méthode complète.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Un bon logo se lit en petit, fonctionne en noir et blanc et dit quelque chose de votre métier ou de votre style. Il ne se choisit pas sur un coup de cœur.</li> <li>La méthode tient en cinq étapes : un brief clair, une vérification de ce qui existe déjà, quelques pistes, des tests en situation, puis les fichiers finaux.</li> <li>Avant de l''imprimer partout, vérifiez qu''il ne ressemble pas à une marque existante. Demandez aussi les fichiers sources et une cession des droits écrite.</li> </ul> </div> <p>Le logo, c''est la première chose qu''un client voit : sur la camionnette, l''enseigne, la page Facebook, le devis. Pourtant, beaucoup d''entreprises le font en une soirée, sur un générateur en ligne ou avec un neveu doué, puis le gardent dix ans sans savoir s''il les sert vraiment.</p> <p>Voici la méthode en cinq étapes pour obtenir un logo qui tient la route, que vous le fassiez faire par un graphiste ou que vous cadriez le travail vous-même.</p> <h2>Ce qu''un bon logo doit réussir</h2> <ul class="checklist"> <li><strong>Être lisible en petit</strong> : en photo de profil Facebook, en icône de site, en tampon sur un devis.</li> <li><strong>Fonctionner en une seule couleur</strong> : en noir sur un ticket de caisse, en blanc sur une photo, en broderie sur un polo.</li> <li><strong>Rester simple</strong> : deux couleurs, une ou deux polices au maximum, peu de détails.</li> <li><strong>Vous ressembler</strong> : un traiteur créole et un cabinet d''expertise comptable n''ont pas besoin du même ton.</li> <li><strong>Durer</strong> : éviter les effets à la mode qui datent vite.</li> </ul> <h2>La méthode en 5 étapes</h2> <ol class="etapes"> <li><strong>Le brief.</strong> Sur une page : ce que vous faites, pour qui, ce qui vous distingue, trois mots qui décrivent votre style (« artisanal, chaleureux, fiable »), les couleurs à éviter, et où le logo sera utilisé. Ajoutez deux ou trois logos que vous aimez, et dites pourquoi.</li> <li><strong>La vérification de l''existant.</strong> Regardez ce que font vos concurrents sur l''île, pour ne pas leur ressembler. Cherchez aussi votre nom dans la base des marques de l''INPI pour éviter un conflit.</li> <li><strong>Les pistes.</strong> Deux ou trois propositions différentes, pas dix variantes de la même. Chacune doit répondre au brief d''une façon distincte : une typographique, une avec un symbole, par exemple.</li> <li><strong>Les tests en situation.</strong> Placez chaque piste sur une maquette de camionnette, une photo de profil, un devis, en noir et blanc et en petit. C''est souvent là qu''une piste séduisante sur grand écran s''écroule.</li> <li><strong>Les fichiers finaux.</strong> La version principale, une version horizontale ou carrée, une version en une couleur, et les fichiers sources (vectoriels) pour l''imprimeur, avec les codes des couleurs et le nom des polices.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Brief type, à adapter</p> <p>« Menuiserie familiale à Saint-Joseph, meubles sur mesure en bois local. Clients : particuliers qui rénovent. Style : artisanal, solide, chaleureux. À éviter : le vert vif, les effets brillants. Utilisations : camionnette, devis, page Facebook, gravure au fer sur les meubles. Nous aimons le logo X pour sa simplicité, et pas le logo Y, trop chargé. »</p> </div> <h2>Protéger son logo</h2> <p>Un logo peut être déposé comme marque à l''<a href="https://www.inpi.fr/realiser-demarches/propriete-intellectuelle/deposant-et-cout-dune-marque" target="_blank" rel="noopener">INPI</a>. Le dépôt en ligne coûte 190 € pour une classe de produits ou services, plus 40 € par classe supplémentaire (tarif indiqué par l''INPI, à vérifier au moment du dépôt). La protection dure 10 ans et se renouvelle. L''INPI recommande de vérifier au préalable la disponibilité du signe dans sa base de marques gratuite.</p> <p>Si un graphiste ou une agence crée votre logo, demandez une cession des droits écrite, qui précise ce que vous pouvez en faire (impression, web, enseigne, modifications), et récupérez les fichiers sources. Sans cela, faire évoluer ou déposer le logo peut devenir compliqué.</p> <table class="table-article"> <thead><tr><th>Ce qu''il faut récupérer</th><th>Pourquoi</th></tr></thead> <tbody> <tr><td>Fichiers vectoriels (SVG, PDF, AI ou EPS)</td><td>Agrandir le logo sans perte, pour l''enseigne ou le flocage</td></tr> <tr><td>Fichiers PNG sur fond transparent</td><td>Le site, les réseaux, les documents</td></tr> <tr><td>Version en une couleur</td><td>Tampon, gravure, impression économique</td></tr> <tr><td>Codes couleurs et noms des polices</td><td>Garder la même identité sur tous vos supports</td></tr> <tr><td>Cession des droits écrite</td><td>Pouvoir utiliser, modifier et déposer le logo sans dépendre du créateur</td></tr> </tbody> </table> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un food truck à Saint-Pierre</p> <p>Le gérant avait un logo très détaillé, avec un camion dessiné, une marmite et un slogan. Sur la photo de profil Instagram, on ne lisait plus rien. Il repart d''un brief, choisit une piste typographique avec un seul symbole simple, la teste en petit et sur le camion, puis cherche le nom dans la base de l''INPI avant de faire floquer le véhicule.</p> </div> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>Logo seul avec 2 propositions : 190 €. Logo et charte graphique avec 3 propositions : 490 €. Logo, charte complète et brand book : 900 €. Le Pack de lancement (499 €) comprend la création ou la refonte du logo, avec 3 propositions et 2 séries de révisions, ses déclinaisons pour le web et l''impression, les fichiers sources et la mise en place de votre page Facebook professionnelle.</p> <p><a href="/services#identite-visuelle" class="encadre-lien">Voir l''offre Identité visuelle</a> · <a href="/solutions#lancement" class="encadre-lien">Le Pack de lancement</a></p> </div> <h2>Questions fréquentes</h2> <h3>Combien coûte un logo professionnel ?</h3> <p>Les prix varient beaucoup selon ce qui est inclus : nombre de propositions, de révisions, charte graphique, fichiers sources. Comparez les devis sur ces points plutôt que sur le seul prix. À titre de repère, la grille de DIGITA commence à 190 € pour un logo seul.</p> <h3>Faut-il déposer son logo à l''INPI ?</h3> <p>Ce n''est pas obligatoire, mais c''est conseillé si vous comptez développer la marque, ouvrir d''autres points de vente ou vendre des produits sous ce nom. Vérifiez d''abord dans la base de l''INPI qu''une marque proche n''existe pas déjà.</p> <h3>Peut-on utiliser un générateur de logo en ligne ?</h3> <p>Pour tester une idée, oui. Mais ces outils reprennent souvent les mêmes symboles pour tout le monde, ce qui rend le logo peu distinctif et parfois difficile à protéger. Vérifiez aussi les conditions d''utilisation : certains limitent l''usage commercial ou les fichiers fournis.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.inpi.fr/realiser-demarches/propriete-intellectuelle/deposant-et-cout-dune-marque" target="_blank" rel="noopener">INPI : déposant et coût d''une marque</a>.</li> <li><a href="https://www.inpi.fr/realiser-demarches/propriete-intellectuelle/marque-apres-son-depot" target="_blank" rel="noopener">INPI : votre marque après son dépôt (durée, renouvellement)</a>.</li> <li><a href="https://www.inpi.fr/ressources/propriete-intellectuelle/rechercher-une-marque-base-marques" target="_blank" rel="noopener">INPI : rechercher une marque dans la base marques</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a> et <a href="/solutions#lancement">Pack de lancement</a>, consultés le 8 novembre 2026.</li> </ul> </div>', 'Créer un logo professionnel : la méthode en 5 étapes', 'Brief, vérification de l''existant, pistes, tests en petit, fichiers sources : la méthode pour un logo d''entreprise qui dure, et comment le protéger à l''INPI.', 'créer un logo, logo entreprise Réunion, logo professionnel, déposer logo INPI, charte graphique', '/assets/images/blog/creer-logo-entreprise.webp', '/assets/images/blog/creer-logo-entreprise.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;

INSERT INTO blog_articles (title, slug, category_id, service_name, excerpt, content, meta_title, meta_description, meta_keywords, featured_image, image_url, status, created_at, updated_at)
VALUES ('Facture électronique : ce qui change pour les TPE en 2026 et 2027', 'facture-electronique-tpe', (SELECT id FROM service_categories WHERE slug = 'intelligence-artificielle'), 'Automatisation', 'La réception est déjà obligatoire, l''émission arrive en septembre 2027. Calendrier, plateformes agréées, nouvelles mentions : ce qu''une petite entreprise doit faire.', '<div class="en-bref"> <p class="en-bref-titre">En bref</p> <ul> <li>Depuis le 1er septembre 2026, toutes les entreprises assujetties à la TVA, TPE et micro-entreprises comprises, doivent pouvoir recevoir des factures électroniques.</li> <li>À partir du 1er septembre 2027, les PME, TPE et micro-entreprises devront aussi les émettre sous forme électronique, et transmettre certaines données à l''administration.</li> <li>Tout passe par une plateforme agréée, choisie dans la liste publiée par impots.gouv.fr. Parlez-en à votre expert-comptable dès maintenant.</li> </ul> </div> <p>« Facture électronique ? J''envoie déjà mes factures en PDF par e-mail. » C''est la réaction la plus courante, et elle cache un malentendu : un PDF envoyé par e-mail n''est pas une facture électronique au sens de la réforme. Celle-ci impose un format structuré, échangé par une plateforme agréée, que l''administration peut lire.</p> <p>La bonne nouvelle pour une petite entreprise : vous avez jusqu''au 1er septembre 2027 pour émettre. Mais la réception, elle, est déjà obligatoire. Voici ce qui change, et comment s''y préparer sans stress.</p> <h2>Le calendrier</h2> <table class="table-article"> <thead><tr><th>Date</th><th>Qui</th><th>Ce qui est obligatoire</th></tr></thead> <tbody> <tr><td>1er septembre 2026</td><td>Toutes les entreprises assujetties à la TVA, quelle que soit leur taille</td><td>Pouvoir recevoir des factures électroniques</td></tr> <tr><td>1er septembre 2026</td><td>Grandes entreprises et ETI</td><td>Émettre des factures électroniques et transmettre les données de transaction et de paiement</td></tr> <tr><td>1er septembre 2027</td><td>PME, TPE et micro-entreprises</td><td>Émettre des factures électroniques et transmettre les données (e-reporting)</td></tr> </tbody> </table> <p>Les micro-entrepreneurs en franchise en base de TVA sont concernés eux aussi : l''administration précise qu''ils restent des assujettis, même s''ils ne facturent pas la TVA.</p> <h2>Ce que la réforme change vraiment</h2> <ul> <li><strong>Un format structuré</strong> : la facture contient des données lisibles par un logiciel, et plus seulement une image du document.</li> <li><strong>Une plateforme agréée</strong> : c''est un opérateur immatriculé par l''État, qui émet, reçoit et transmet les factures, et envoie les données utiles à l''administration. On l''appelait auparavant PDP.</li> <li><strong>L''e-reporting</strong> : pour les ventes aux particuliers et les opérations avec l''étranger, il n''y a pas de facture électronique à émettre, mais des données de transaction à transmettre.</li> <li><strong>De nouvelles mentions</strong> sur les factures, obligatoires pour les PME et micro-entreprises à partir du 1er septembre 2027 : le numéro SIREN du client, l''adresse de livraison si elle diffère, la nature de l''opération (biens, services ou les deux), et la mention « Option pour le paiement de la taxe d''après les débits » si vous avez choisi cette option.</li> </ul> <h2>Se préparer en 5 étapes</h2> <ol class="etapes"> <li><strong>Faire le point avec votre expert-comptable.</strong> Il sait quelle plateforme il utilise ou recommande, et comment vos factures arrivent dans votre comptabilité.</li> <li><strong>Choisir une plateforme agréée</strong> dans la <a href="https://www.impots.gouv.fr/je-consulte-la-liste-des-plateformes-agreees" target="_blank" rel="noopener">liste officielle d''impots.gouv.fr</a>. Votre logiciel de facturation actuel est peut-être déjà raccordé à l''une d''elles : posez-lui la question.</li> <li><strong>Vérifier la réception dès maintenant.</strong> Vos fournisseurs de grande taille émettent déjà des factures électroniques : vous devez pouvoir les recevoir.</li> <li><strong>Mettre à jour vos fiches clients</strong> : SIREN de chaque client professionnel, adresses de livraison. C''est le travail le plus long, autant le commencer tôt.</li> <li><strong>Tester avant l''échéance.</strong> Émettez quelques factures par la plateforme bien avant le 1er septembre 2027, pour régler les problèmes à froid.</li> </ol> <div class="encadre-exemple"> <p class="encadre-titre">Exemple (cas fictif) : un électricien à Sainte-Marie</p> <p>Il fait ses factures sur un tableur et les envoie en PDF. En octobre 2026, son grossiste lui annonce que ses factures arrivent désormais par une plateforme. Avec son comptable, il choisit un logiciel de facturation raccordé à une plateforme agréée, reçoit dessus les factures du grossiste, et profite de l''hiver pour compléter le SIREN de ses clients professionnels. Il émettra ses propres factures par le logiciel bien avant septembre 2027.</p> </div> <h2>Et à La Réunion ?</h2> <p>La réforme vise les entreprises établies en France et assujetties à la TVA. La TVA s''applique à La Réunion, et les entreprises de l''île sont donc concernées par le même calendrier. Certaines situations propres aux départements d''outre-mer, comme les échanges avec la métropole, peuvent avoir des règles particulières : faites-les vérifier par votre expert-comptable ou dans la documentation d''impots.gouv.fr.</p> <div class="encadre-digita"> <p class="encadre-titre">Ce que fait DIGITA</p> <p>DIGITA n''est pas une plateforme agréée et ne remplace pas votre expert-comptable. Nous pouvons en revanche automatiser ce qui entoure vos factures : relance des devis et des factures impayées, et autres tâches répétitives, à partir de 490 €, payés une fois.</p> <p><a href="/services#ia-automation" class="encadre-lien">Voir l''offre Automatisation</a> · <a href="/diagnostic" class="encadre-lien">Réserver un diagnostic gratuit</a></p> </div> <h2>Questions fréquentes</h2> <h3>Une facture en PDF envoyée par e-mail est-elle une facture électronique ?</h3> <p>Non, pas au sens de la réforme. La facture électronique doit être émise dans un format structuré et passer par une plateforme agréée. Le PDF simple reste possible pour une PME jusqu''à son obligation d''émission, le 1er septembre 2027.</p> <h3>Un micro-entrepreneur est-il concerné par la facture électronique ?</h3> <p>Oui. Même en franchise en base de TVA, il doit pouvoir recevoir des factures électroniques depuis le 1er septembre 2026, et les émettre à partir du 1er septembre 2027.</p> <h3>Comment choisir sa plateforme agréée ?</h3> <p>Partez de la liste officielle publiée sur impots.gouv.fr, et demandez conseil à votre expert-comptable. Vérifiez que la plateforme se connecte à votre logiciel de facturation et de comptabilité, et comparez les tarifs selon votre volume de factures.</p> <div class="article-sources"> <p class="encadre-titre">Sources</p> <ul> <li><a href="https://www.impots.gouv.fr/professionnel/je-passe-la-facturation-electronique" target="_blank" rel="noopener">impots.gouv.fr : je passe à la facturation électronique</a>.</li> <li><a href="https://www.impots.gouv.fr/professionnel/questions/partir-de-quand-suis-je-concerne-par-la-reforme-de-la-facturation" target="_blank" rel="noopener">impots.gouv.fr : à partir de quand suis-je concerné par la réforme ?</a></li> <li><a href="https://www.impots.gouv.fr/professionnel/questions/franchise-en-base-micro-entrepreneur-ou-auto-entrepreneur-suis-je-concerne" target="_blank" rel="noopener">impots.gouv.fr : franchise en base, micro-entrepreneur, suis-je concerné ?</a></li> <li><a href="https://www.impots.gouv.fr/je-consulte-la-liste-des-plateformes-agreees" target="_blank" rel="noopener">impots.gouv.fr : liste des plateformes agréées</a>.</li> <li><a href="https://entreprendre.service-public.gouv.fr/vosdroits/F39785" target="_blank" rel="noopener">Service Public Entreprendre : facturation électronique</a>.</li> <li><a href="https://entreprendre.service-public.gouv.fr/vosdroits/F31808" target="_blank" rel="noopener">Service Public Entreprendre : mentions obligatoires sur une facture</a>.</li> <li>Grille tarifaire DIGITA : <a href="/tarifs">page Tarifs</a>, consultée le 8 novembre 2026.</li> </ul> </div>', 'Facture électronique : ce qui change pour les TPE', 'Réception obligatoire depuis septembre 2026, émission en septembre 2027 : le calendrier de la facture électronique pour les TPE, et comment s''y préparer.', 'facture électronique TPE, facturation électronique 2026, plateforme agréée, e-reporting, micro-entreprise facture électronique', '/assets/images/blog/facture-electronique-tpe.webp', '/assets/images/blog/facture-electronique-tpe.webp', 'draft', NOW(), NOW())
ON CONFLICT (slug) DO NOTHING;
